def get_expanded_v2_rosetta():
    """Return all v2 expanded handcrafted entries."""
    entries = []
    idx = 20000
    for concept, lang_codes in EXPANDED_V2.items():
        cn = concept.replace('_', ' ').title()
        for lang, code in lang_codes.items():
            idx += 1
            entries.append({
                "id": f"rosetta_v2_{idx}",
                "concept": concept,
                "concept_name": cn,
                "language": lang,
                "code": code,
                "category": "rosetta_stone",
                "has_code": True,
                "code_lines": len(code.split('\n')),
                "source": "handcrafted",
            })
    return entries